CREATE TABLE IF NOT EXISTS admin_settings (key TEXT PRIMARY KEY,value TEXT,updated_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS site_visits (id SERIAL PRIMARY KEY,path TEXT NOT NULL,visited_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS posts (id SERIAL PRIMARY KEY,title TEXT NOT NULL,title_en TEXT,content TEXT,content_en TEXT,image_url TEXT,category TEXT,published INTEGER DEFAULT 1,created_at TIMESTAMPTZ DEFAULT NOW(),updated_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS products (id SERIAL PRIMARY KEY,title TEXT NOT NULL,title_en TEXT,description TEXT,description_en TEXT,category TEXT NOT NULL DEFAULT 'refrigerator',price NUMERIC(12,2),previous_price NUMERIC(12,2),comparison_evidence TEXT,price_note TEXT,price_note_en TEXT,condition TEXT,condition_en TEXT,reference TEXT,dimensions TEXT,dimensions_en TEXT,defects TEXT,defects_en TEXT,image_url TEXT,image_url_2 TEXT,photos_verified BOOLEAN DEFAULT FALSE,facts_verified BOOLEAN DEFAULT FALSE,featured BOOLEAN DEFAULT FALSE,published INTEGER DEFAULT 0,created_at TIMESTAMPTZ DEFAULT NOW(),updated_at TIMESTAMPTZ DEFAULT NOW());